    // MARK: Type. SF for all UI text (follows system settings); Fraunces only for display moments (bundled, OFL).
    enum Family: String, Sendable { case sf, sfMono, fraunces }
    struct TypeSpec: Sendable, Equatable {
        let family: Family
        let size: CGFloat
        let weight: Int
        let lineHeight: CGFloat
        let tracking: CGFloat
        let tabular: Bool
        var fontWeight: Font.Weight {
            switch weight { case ..<350: .light; case ..<450: .regular; case ..<550: .medium; case ..<650: .semibold; default: .bold }
        }
        /// Fraunces is registered at launch (RoomDisplayFont.register()); if it is missing, Font.custom falls back to SF.
        var font: Font {
            let base: Font
            switch family {
            case .sf: base = .system(size: size, weight: fontWeight)
            case .sfMono: base = .system(size: size, weight: fontWeight, design: .monospaced)
            case .fraunces: base = Font.custom(RoomDS.displayFamilyName, fixedSize: size).weight(fontWeight)
            }
            return tabular ? base.monospacedDigit() : base
        }
        /// Extra leading to reach lineHeight from the font's natural line height (approximate: 1.2 x size).
        var lineSpacing: CGFloat { max(0, lineHeight - size * 1.2) }
    }
    static let displayFamilyName = "Fraunces"
    enum TypeRole: String, CaseIterable, Sendable {
        case displayXl, display, h1, h2, lead, body, small, label, numberXl, number, mono
        var spec: TypeSpec {
            switch self {
            case .displayXl: TypeSpec(family: .fraunces, size: 34, weight: 600, lineHeight: 38, tracking: -0.6, tabular: false)
            case .display: TypeSpec(family: .fraunces, size: 26, weight: 500, lineHeight: 30, tracking: -0.3, tabular: false)
            case .h1: TypeSpec(family: .sf, size: 15, weight: 600, lineHeight: 20, tracking: 0, tabular: false)
            case .h2: TypeSpec(family: .sf, size: 13, weight: 600, lineHeight: 16, tracking: 0, tabular: false)
            case .lead: TypeSpec(family: .sf, size: 15, weight: 400, lineHeight: 22, tracking: 0, tabular: false)
            case .body: TypeSpec(family: .sf, size: 13, weight: 400, lineHeight: 18, tracking: 0, tabular: false)
            case .small: TypeSpec(family: .sf, size: 12, weight: 400, lineHeight: 16, tracking: 0, tabular: false)
            case .label: TypeSpec(family: .sf, size: 11, weight: 500, lineHeight: 14, tracking: 0, tabular: false)
            case .numberXl: TypeSpec(family: .sf, size: 40, weight: 400, lineHeight: 44, tracking: -0.5, tabular: true)
            case .number: TypeSpec(family: .sf, size: 22, weight: 400, lineHeight: 26, tracking: -0.2, tabular: true)
            case .mono: TypeSpec(family: .sfMono, size: 11.5, weight: 400, lineHeight: 15, tracking: 0, tabular: false)
            }
        }
        var font: Font { spec.font }
    }
    static let unitScale: CGFloat = 0.4
    static let unitMinimum: CGFloat = 14
    static let textFloor: CGFloat = 11
    /// The unit beside a figure (GB): 0.4 x figure, at least 14, regular weight.
    static func unitFont(for figureSize: CGFloat) -> Font { .system(size: max(unitMinimum, figureSize * unitScale), weight: .regular) }

