    // MARK: Motion. Four durations, two curves, three springs. Same names on the web (room-tokens.css).
    enum Motion {
        enum Duration: String, CaseIterable, Sendable {
            case quick, standard, page, slow
            var milliseconds: Int {
                switch self {
                case .quick: 120
                case .standard: 200
                case .page: 320
                case .slow: 600
                }
            }
            var seconds: TimeInterval { TimeInterval(milliseconds) / 1000 }
        }
        struct Curve: Sendable, Equatable { let x1: Double, y1: Double, x2: Double, y2: Double }
        static let out = Curve(x1: 0.23, y1: 1, x2: 0.32, y2: 1)
        static let inOut = Curve(x1: 0.65, y1: 0, x2: 0.35, y2: 1)
        static let linear = Curve(x1: 0, y1: 0, x2: 1, y2: 1)
        struct SpringSpec: Sendable, Equatable {
            let response: Double
            let damping: Double
            var animation: Animation { .spring(response: response, dampingFraction: damping) }
        }
        enum Spring: String, CaseIterable, Sendable {
            case page, slow, success
            var spec: SpringSpec {
                switch self {
                case .page: SpringSpec(response: 0.32, damping: 1)
                case .slow: SpringSpec(response: 0.6, damping: 1)
                case .success: SpringSpec(response: 0.28, damping: 0.7)
                }
            }
        }
        static func timed(_ duration: Duration, _ curve: Curve = out) -> Animation {
            .timingCurve(curve.x1, curve.y1, curve.x2, curve.y2, duration: duration.seconds)
        }
        static let staggerItem: TimeInterval = 0.03
        static let staggerCap = 12
        static let staggerDot: TimeInterval = 0.016
        static let dotSpreadCap: TimeInterval = 0.6
        static let staggerGroup: TimeInterval = 0.07
        static let tooltipDelay: TimeInterval = 0.5
        static let pressScale: CGFloat = 0.96
        static let pressReducedOpacity: Double = 0.7
        static let reduceMotionCrossfade = Duration.standard
        /// Delay for the i-th item of a staggered list (capped at staggerCap items).
        static func stagger(_ index: Int) -> TimeInterval { Double(min(index, staggerCap - 1)) * staggerItem }
        /// The shared vocabulary. Each entry names its duration token and curve; Reduce Motion uses `reduce`.
        enum Reduce: String, Sendable { case fade, swap, opacity }
        struct Move: Sendable { let name: String; let duration: Duration; let curve: String; let stagger: String; let reduce: Reduce; let web: String }
        enum Vocabulary: String, CaseIterable, Sendable {
            case dotsAssemble, ringsBreathe, pocketFills, receiptLights, kindLights, press, stepInside, countChange, toast, madeRoom
            var move: Move {
                switch self {
                case .dotsAssemble: Move(name: "dotsAssemble", duration: .slow, curve: "spring.slow", stagger: "dot", reduce: .fade, web: "room-dots-assemble")
                case .ringsBreathe: Move(name: "ringsBreathe", duration: .slow, curve: "easing.out", stagger: "none", reduce: .fade, web: "room-rings-breathe")
                case .pocketFills: Move(name: "pocketFills", duration: .standard, curve: "easing.out", stagger: "none", reduce: .swap, web: "room-pocket-fills")
                case .receiptLights: Move(name: "receiptLights", duration: .slow, curve: "easing.out", stagger: "item", reduce: .fade, web: "room-receipt-lights")
                case .kindLights: Move(name: "kindLights", duration: .standard, curve: "easing.out", stagger: "none", reduce: .swap, web: "room-kind-lights")
                case .press: Move(name: "press", duration: .quick, curve: "easing.out", stagger: "none", reduce: .opacity, web: "room-press")
                case .stepInside: Move(name: "stepInside", duration: .page, curve: "spring.page", stagger: "none", reduce: .fade, web: "room-step-inside")
                case .countChange: Move(name: "countChange", duration: .page, curve: "easing.out", stagger: "none", reduce: .swap, web: "room-count")
                case .toast: Move(name: "toast", duration: .standard, curve: "easing.out", stagger: "none", reduce: .fade, web: "room-toast")
                case .madeRoom: Move(name: "madeRoom", duration: .page, curve: "spring.success", stagger: "none", reduce: .swap, web: "room-made")
                }
            }
            /// Full-motion animation for this move.
            var animation: Animation {
                let mv = move
                if mv.curve.hasPrefix("spring."), let spring = Spring(rawValue: String(mv.curve.dropFirst(7))) { return spring.spec.animation }
                return Motion.timed(mv.duration, mv.curve == "easing.inOut" ? Motion.inOut : Motion.out)
            }
            /// Reduce Motion: a crossfade at the standard duration, or nothing (instant swap).
            var reducedAnimation: Animation? { move.reduce == .swap ? nil : Motion.timed(reduceMotionCrossfade) }
        }
    }

