        static let posterRingStrokeFactor: CGFloat = 0.054
        static let unitSteps: [Double] = [1, 2, 4, 8, 16, 32]
        static let maxDots = 320
        /// Rest radius for a pitch at product scale (0.15 x pitch, clamped 2.4 ... 3.6).
        static func radius(pitch: CGFloat) -> CGFloat { min(radiusMax, max(radiusMin, pitch * radiusFactor)) }
    }

